(()=>{const s=document.createElement('script');s.text="async function renderAnalysis(events){const sorted=[...events].sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)),cycle=currentCycle(sorted),latestNote=sorted.find(e=>e.type==='note'),cycleMeds=sorted.filter(e=>e.type==='medication'&&new Date(e.timestamp).getTime()>=cycle.start),contextStart=cycle.start-24*3600000,contextMeds=cycle.lastSleep?sorted.filter(e=>e.type==='medication'&&new Date(e.timestamp).getTime()<cycle.start&&new Date(e.timestamp).getTime()>=contextStart):[],lastSleep=cycle.lastSleep||sorted.find(e=>e.type==='sleep');document.getElementById('currentAnalysis').innerHTML=[analysisRow('Período considerado',cycle.label),analysisRow('Último relato',latestNote?`“${latestNote.text||'Anotação de voz'}” · ${humanAgo(latestNote.timestamp)}`:'Ainda não há anotações.'),analysisRow(cycle.lastSleep?'Medicamentos desde que acordou':'Medicamentos recentes',cycleMeds.length?cycleMeds.map(medicationEventLabel).join(' · '):'Nenhum registro nesse período.'),...(contextMeds.length?[analysisRow('Contexto antes do último sono',contextMeds.map(medicationEventLabel).join(' · '))]:[]),analysisRow('Sono mais recente',lastSleep?`${durationLabel(durationHours(lastSleep.startTime,lastSleep.endTime))}${lastSleep.quality?` · qualidade ${lastSleep.quality}`:''}`:'Ainda não há registros de sono.')].join('');const admins=sorted.filter(e=>e.type==='medication'),notes=sorted.filter(e=>e.type==='note'&&e.text),grouped={};for(const a of admins){const key=a.medication||'Medicamento';if(!grouped[key])grouped[key]={count:0,terms:[]};const st=new Date(a.timestamp).getTime(),en=st+8*3600000,nearby=notes.filter(n=>{const t=new Date(n.timestamp).getTime();return t>=st&&t<=en});grouped[key].count+=nearby.length;grouped[key].terms.push(...nearby.flatMap(n=>moodTerms(n.text)))}const assoc=Object.entries(grouped).sort((a,b)=>b[1].count-a[1].count).slice(0,4);document.getElementById('associationAnalysis').innerHTML=assoc.length?assoc.map(([name,data])=>{const c={};data.terms.forEach(t=>c[t]=(c[t]||0)+1);const common=Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([t,n])=>`${t} (${n})`).join(', ');return analysisRow(name,`${data.count} anotação(ões) até 8h depois de administrações${common?`. Termos recorrentes: ${common}`:''}.`) }).join(''):analysisRow('Ainda sem padrão','Registre administrações e anotações ao longo do tempo.');const sleeps=sorted.filter(e=>e.type==='sleep'),avg=sleeps.length?sleeps.reduce((s,e)=>s+durationHours(e.startTime,e.endTime),0)/sleeps.length:null,qs=sleeps.filter(e=>Number(e.quality)),avgQ=qs.length?qs.reduce((s,e)=>s+Number(e.quality),0)/qs.length:null;document.getElementById('sleepAnalysis').innerHTML=[metric(avg==null?'—':durationLabel(avg),'Média de duração'),metric(avgQ==null?'—':avgQ.toFixed(1),'Qualidade média'),metric(String(sleeps.length),'Noites registradas'),metric(sleeps[0]?durationLabel(durationHours(sleeps[0].startTime,sleeps[0].endTime)):'—','Último sono')].join('');const meds=await allMedications();const medRows=[];for(const m of meds){const c=medicationCostSummary(m,sorted);if(c)medRows.push(analysisRow(m.activeIngredient,`Último custo: ${c.unit!=null?`${money(c.unit)}/unidade`: 'sem unidades definidas'}${c.monthly!=null?` · gasto registrado nos últimos 30 dias ≈ ${money(c.monthly)}`:''}`))}document.getElementById('medicationAnalysis').innerHTML=medRows.length?medRows.slice(0,6).join(''):analysisRow('Cadastre apresentações','Com unidades por caixa, compras e administrações o app calcula custo e duração.');const buys=sorted.filter(e=>e.type==='purchase'),groups={};for(const p of buys){const n=parseMoney(p.price);if(n==null)continue;(groups[p.medication||'Medicamento']??=[]).push(n)}const priceRows=Object.entries(groups).slice(0,5);document.getElementById('purchaseAnalysis').innerHTML=priceRows.length?priceRows.map(([name,vals])=>analysisRow(name,`${vals.length} compra(s) · média ${money(vals.reduce((a,b)=>a+b,0)/vals.length)} · menor ${money(Math.min(...vals))} · maior ${money(Math.max(...vals))}`)).join(''):analysisRow('Ainda sem histórico de preço','Registre compras com valor para comparar preços.')}\n\nasync function renderAll(){const events=(await allEvents()).sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp));await renderHome(events);await renderHistory(events);await renderAnalysis(events);renderBackupState();renderHealthState();applySettings()}\n\nfunction dateField(id,label,value,{showNow=false,reserveNow=true}={}){const rowClass=reserveNow?'date-row':'date-row no-now-column';const slot=reserveNow?`<span class=\"now-slot ${showNow?'':'empty'}\">${showNow?'<span class=\"now-tag\">agora</span>':''}</span>`:'';return`<div class=\"field\"><label for=\"${id}\">${label}</label><div class=\"${rowClass}\"><input class=\"date-input\" type=\"datetime-local\" id=\"${id}\" value=\"${value}\" ${showNow?`data-now-base=\"${value}\"`:''}>${slot}</div></div>`}\nfunction activateNowTags(root=document){root.querySelectorAll('.date-input[data-now-base]').forEach(input=>{const row=input.closest('.date-row'),slot=row?.querySelector('.now-slot'),update=()=>{if(slot)slot.classList.toggle('empty',input.value!==input.dataset.nowBase)};input.addEventListener('input',update);input.addEventListener('change',update);update()})}\nfunction qualitySelector(value=4){return`<div class=\"sleep-quality\" id=\"sleepQuality\">${[1,2,3,4,5].map(q=>`<button type=\"button\" data-quality=\"${q}\" class=\"${Number(value)===q?'selected':''}\" aria-pressed=\"${Number(value)===q}\"><span class=\"q-dot\"></span><strong>${q}</strong></button>`).join('')}</div><input type=\"hidden\" id=\"sleepQualityValue\" value=\"${Number(value)||4}\">`}\nfunction wireQualitySelector(){document.querySelectorAll('#sleepQuality [data-quality]').forEach(b=>b.onclick=()=>{document.querySelectorAll('#sleepQuality [data-quality]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('sleepQualityValue').value=b.dataset.quality})}\nfunction formButtons(label='Salvar'){return`<div class=\"form-actions\"><button type=\"button\" class=\"secondary-button\" data-cancel>Cancelar</button><button type=\"submit\" class=\"primary-button\">${label}</button></div>`}\nfunction openBackdrop(title,html,onSubmit){currentType=null;document.getElementById('sheetTitle').textContent=title;const form=document.getElementById('form');form.innerHTML=html;form.onsubmit=onSubmit||((e)=>e.preventDefault());form.querySelector('[data-cancel]')?.addEventListener('click',closeSheet);document.getElementById('backdrop').classList.add('open');document.getElementById('backdrop').setAttribute('aria-hidden','false');hydrateIcons(form);activateNowTags(form)}\nfunction closeSheet(){if(mediaRecorder?.state==='recording')mediaRecorder.stop();document.getElementById('backdrop').classList.remove('open');document.getElementById('backdrop').setAttribute('aria-hidden','true');pendingAudio=null;selectedMedicationId=null;selectedPresentationId=null;currentType=null}\n\nasync function typicalMedicationSuggestion(){const meds=await allMedications(),events=await allEvents(),now=currentMinutes(),candidates=[];for(const m of meds){const times=events.filter(e=>e.type==='medication'&&medMatchesEvent(m,e)).map(e=>{const d=new Date(e.timestamp);return d.getHours()*60+d.getMinutes()});if(times.length<2)continue;const x=times.reduce((s,t)=>s+Math.cos(t/1440*2*Math.PI),0),y=times.reduce((s,t)=>s+Math.sin(t/1440*2*Math.PI),0);let ang=Math.atan2(y,x);if(ang<0)ang+=2*Math.PI;const avg=ang/(2*Math.PI)*1440,dist=minuteDistance(avg,now);if(dist<=150)candidates.push({m,dist,avg,count:times.length})}return candidates.sort((a,b)=>a.dist-b.dist||b.count-a.count)[0]||null}\nasync function medicationSuggestions(query){const meds=await allMedications();return meds.map(m=>({m,score:medSearchScore(m,query)})).filter(x=>x.score<4).sort((a,b)=>a.score-b.score).slice(0,5).map(x=>x.m)}\nfunction autocompleteHTML(){return'<div class=\"autocomplete-results hidden\" id=\"medAutocomplete\"></div>'}\n";document.head.appendChild(s);s.remove();})();

