(()=>{const s=document.createElement('script');s.text="async function updatePurchasePreview(){const meds=await allMedications(),m=meds.find(x=>x.id===selectedMedicationId),p=findPresentation(m,selectedPresentationId),price=parseMoney(document.getElementById('purchasePrice')?.value),packages=Number(document.getElementById('purchasePackages')?.value)||1,units=Number(p?.unitsPerPackage)||0,blister=Number(p?.unitsPerBlister)||0,box=document.getElementById('purchaseCostPreview'),text=document.getElementById('purchaseCostText');if(!box||!text)return;if(price!=null&&units){const perUnit=price/(packages*units),perBlister=blister?perUnit*blister:null;text.textContent=`${money(perUnit)} por unidade${perBlister!=null?` · ${money(perBlister)} por cartela`:''}`;box.classList.remove('hidden')}else box.classList.add('hidden')}\n\nfunction openSleepSheet(payload=null){currentType='sleep';pendingSleepSource=payload?'health-shortcut':'manual';const now=toLocalInput(),start=payload?.start?toLocalInput(payload.start):toLocalInput(new Date(Date.now()-8*3600000).toISOString()),end=payload?.end?toLocalInput(payload.end):now,reserve=!payload;openBackdrop(payload?'Revisar sono importado':'Registrar sono',`${dateField('sleepStart','Dormiu às',start,{showNow:false,reserveNow:reserve})}${dateField('sleepEnd','Acordou às',end,{showNow:!payload,reserveNow:reserve})}<div class=\"field\"><label>Qualidade percebida</label>${qualitySelector(payload?.quality||4)}</div><div class=\"field\"><label for=\"sleepNote\">Observações opcionais</label><textarea id=\"sleepNote\" rows=\"4\" style=\"overflow:hidden;resize:none\" onfocus=\"this.style.height='auto';this.style.height=this.scrollHeight+'px'\" oninput=\"this.style.height='auto';this.style.height=this.scrollHeight+'px'\" placeholder=\"Ex.: acordei duas vezes, tive pesadelos…\">${esc(payload?.note||'')}</textarea></div><p class=\"helper\">O horário de dormir começa em 8h atrás apenas como sugestão e nunca recebe a tag “agora”.</p>${formButtons(payload?'Salvar importação':'Salvar')}`,saveForm);currentType='sleep';wireQualitySelector()}\n\nfunction setupVoice(){const button=document.getElementById('voiceBtn'),status=document.getElementById('voiceStatus');if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){button.disabled=true;status.textContent='Use o ditado do teclado para transformar voz em texto.';return}button.onclick=async()=>{try{if(mediaRecorder?.state==='recording'){mediaRecorder.stop();return}const stream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];mediaRecorder=new MediaRecorder(stream);mediaRecorder.ondataavailable=e=>{if(e.data.size)audioChunks.push(e.data)};mediaRecorder.onstop=()=>{pendingAudio=new Blob(audioChunks,{type:mediaRecorder.mimeType||'audio/webm'});stream.getTracks().forEach(t=>t.stop());button.classList.remove('recording');button.textContent='✓ Voz gravada';status.textContent='Áudio pronto para salvar.'};mediaRecorder.start();button.classList.add('recording');button.textContent='■ Parar';status.textContent='Gravando…'}catch{status.textContent='Não foi possível acessar o microfone. Use o ditado do teclado.'}}}\n\nasync function saveForm(ev){ev.preventDefault();const id=uid(currentType);let record;if(currentType==='note'){const text=document.getElementById('noteText').value.trim();if(!text&&!pendingAudio)return toast('Escreva ou grave uma anotação.');record={id,type:'note',timestamp:new Date(document.getElementById('recordTime').value).toISOString(),text,tag:document.getElementById('noteTag').value.trim(),hasAudio:Boolean(pendingAudio),audioOnly:Boolean(pendingAudio&&!text),demo:false}}else if(currentType==='medication'){const name=document.getElementById('medName').value.trim();if(!name)return toast('Informe o medicamento.');const mode=document.querySelector('[data-dose-mode].selected')?.dataset.doseMode||'perUnit',unit=document.getElementById('doseUnit')?.value||'mg';let totalDoseValue,unitsTaken=1,unitDoseValue=null;if(mode==='total'){totalDoseValue=Number(String(document.getElementById('totalDoseValue').value).replace(',','.'));if(!Number.isFinite(totalDoseValue))return toast('Informe a dose total.')}else{unitDoseValue=Number(String(document.getElementById('unitDoseValue').value).replace(',','.'));unitsTaken=Number(String(document.getElementById('unitsTaken').value||1).replace(',','.'))||1;if(!Number.isFinite(unitDoseValue))return toast('Informe a dose de cada unidade.');totalDoseValue=unitDoseValue*unitsTaken}record={id,type:'medication',timestamp:new Date(document.getElementById('recordTime').value).toISOString(),medication:name,medicationId:selectedMedicationId,presentationId:selectedPresentationId,doseMode:mode,unitDoseValue,totalDoseValue,doseUnit:unit,unitsTaken,dose:`${totalDoseValue.toLocaleString('pt-BR')} ${unit}`,quantity:unitsTaken===1?'1 unidade':`${unitsTaken} unidades`,note:document.getElementById('medNote').value.trim(),demo:false}}else if(currentType==='purchase'){const name=document.getElementById('purchaseMed').value.trim();if(!name)return toast('Informe o medicamento.');const packages=Math.max(1,Number(document.getElementById('purchasePackages').value)||1),meds=await allMedications(),m=meds.find(x=>x.id===selectedMedicationId),p=findPresentation(m,selectedPresentationId),upp=Number(p?.unitsPerPackage)||0;record={id,type:'purchase',timestamp:new Date(document.getElementById('recordTime').value).toISOString(),medication:name,medicationId:selectedMedicationId,presentationId:selectedPresentationId,packages,totalUnits:upp?packages*upp:null,unitsPerPackage:upp||null,price:document.getElementById('purchasePrice').value.trim(),place:document.getElementById('purchasePlace').value.trim(),demo:false}}else if(currentType==='sleep'){const start=new Date(document.getElementById('sleepStart').value),end=new Date(document.getElementById('sleepEnd').value);if(!(start<end))return toast('O horário de acordar precisa ser posterior ao horário de dormir.');record={id,type:'sleep',timestamp:end.toISOString(),startTime:start.toISOString(),endTime:end.toISOString(),quality:Number(document.getElementById('sleepQualityValue').value)||4,note:document.getElementById('sleepNote').value.trim(),source:pendingSleepSource,demo:false}}else return;await putEvent(record);if(pendingAudio)await saveAudio(id,pendingAudio);if(record.type==='sleep'&&record.source==='health-shortcut')localStorage.setItem(LAST_HEALTH_IMPORT_KEY,new Date().toISOString());closeSheet();await renderAll();toast('Registro salvo.')}\n\nasync function openEventMenu(id){const e=(await allEvents()).find(x=>x.id===id);if(!e)return;openBackdrop('Opções do registro',`<div class=\"sheet-options\"><button type=\"button\" class=\"sheet-option\" id=\"detailBtn\">Ver detalhes</button><button type=\"button\" class=\"sheet-option danger\" id=\"deleteBtn\">Excluir registro</button></div>${formButtons('Fechar')}`,(ev)=>{ev.preventDefault();closeSheet()});document.getElementById('detailBtn').onclick=()=>toast(kindInfo(e).title);document.getElementById('deleteBtn').onclick=async()=>{if(confirm('Excluir este registro?')){await deleteEvent(id);closeSheet();await renderAll();toast('Registro excluído.')}}}\n\nasync function openMedicationRegistry(){const meds=(await allMedications()).sort((a,b)=>a.activeIngredient.localeCompare(b.activeIngredient,'pt-BR'));openBackdrop('Medicamentos',`<div class=\"registry-toolbar\"><button type=\"button\" class=\"primary-button\" id=\"addMedicationBtn\">+ Novo</button><button type=\"button\" class=\"secondary-button\" data-cancel>Fechar</button></div><div class=\"registry-list\">${meds.length?meds.map(m=>`<button type=\"button\" class=\"registry-card\" data-open-med=\"${m.id}\"><span><strong>${esc(medicationDisplay(m))}</strong><small>${esc((m.presentations||[]).map(p=>presentationDisplay(p)).join(' · ')||'Sem apresentações')}</small></span><span class=\"registry-meta\">${(m.notes||[]).length} nota(s)</span></button>`).join(''):'<div class=\"registry-empty\">Nenhum medicamento cadastrado ainda.</div>'}</div>`);document.getElementById('addMedicationBtn').onclick=()=>openMedicationEditor();document.querySelectorAll('[data-open-med]').forEach(b=>b.onclick=()=>openMedicationDetail(b.dataset.openMed))}\n";document.head.appendChild(s);s.remove();})();

