(()=>{const s=document.createElement('script');s.text="function medicationEditorHTML(m={}){const p=(m.presentations||[])[0]||{};return`<div class=\"field\"><label>Princípio ativo</label><input id=\"regActive\" value=\"${esc(m.activeIngredient||'')}\" placeholder=\"Ex.: Lisdexanfetamina\"></div><div class=\"field\"><label>Marca/referência opcional</label><input id=\"regReference\" value=\"${esc(m.referenceName||'')}\" placeholder=\"Ex.: Venvanse\"></div><div class=\"field\"><label>Laboratório opcional</label><input id=\"regLab\" value=\"${esc(m.lab||'')}\"></div><p class=\"section-mini-title\">Primeira apresentação</p><div class=\"field-grid\"><div class=\"field\"><label>Dosagem</label><input id=\"regStrength\" inputmode=\"decimal\" value=\"${esc(p.strengthValue||'')}\"></div><div class=\"field\"><label>Unidade</label><select id=\"regStrengthUnit\"><option>mg</option><option>mcg</option><option>g</option><option>mL</option></select></div></div><div class=\"field\"><label>Forma</label><input id=\"regForm\" value=\"${esc(p.form||'')}\" placeholder=\"cápsula, comprimido…\"></div><div class=\"field-grid\"><div class=\"field\"><label>Unidades por caixa</label><input id=\"regUnits\" inputmode=\"numeric\" value=\"${esc(p.unitsPerPackage||'')}\"></div><div class=\"field\"><label>Unidades por cartela</label><input id=\"regBlister\" inputmode=\"numeric\" value=\"${esc(p.unitsPerBlister||'')}\"></div></div>${formButtons(m.id?'Salvar':'Cadastrar')}`}\nfunction openMedicationEditor(m=null){openBackdrop(m?'Editar medicamento':'Novo medicamento',medicationEditorHTML(m||{}),async ev=>{ev.preventDefault();const active=document.getElementById('regActive').value.trim();if(!active)return toast('Informe o princípio ativo.');const strength=document.getElementById('regStrength').value.trim(),existing={...(m||{})};existing.id=existing.id||uid('med');existing.activeIngredient=active;existing.referenceName=document.getElementById('regReference').value.trim();existing.lab=document.getElementById('regLab').value.trim();existing.notes=existing.notes||[];existing.presentations=existing.presentations||[];if(strength){const old=existing.presentations[0]||{id:uid('presentation')};existing.presentations[0]={...old,strengthValue:Number(String(strength).replace(',','.'))||strength,strengthUnit:document.getElementById('regStrengthUnit').value,form:document.getElementById('regForm').value.trim(),unitsPerPackage:Number(document.getElementById('regUnits').value)||'',unitsPerBlister:Number(document.getElementById('regBlister').value)||'',brand:existing.referenceName,lab:existing.lab}}await putMedication(existing);toast('Medicamento salvo.');openMedicationDetail(existing.id)})}\nasync function openMedicationDetail(id){const meds=await allMedications(),m=meds.find(x=>x.id===id);if(!m)return;const events=await allEvents(),cost=medicationCostSummary(m,events),suggestions=medicationNoteSuggestions(m,events);openBackdrop(m.activeIngredient,`<div class=\"analysis-row\"><strong>${esc(medicationDisplay(m))}</strong><span>${esc([m.lab,(m.presentations||[]).length?`${m.presentations.length} apresentação(ões)`:null].filter(Boolean).join(' · ')||'Cadastro básico')}</span></div><div class=\"registry-toolbar\"><button type=\"button\" class=\"secondary-button\" id=\"editMedBtn\">Editar</button><button type=\"button\" class=\"secondary-button\" id=\"addPresentationBtn\">+ Apresentação</button></div><p class=\"section-mini-title\">Apresentações</p><div class=\"presentation-list\">${(m.presentations||[]).length?(m.presentations||[]).map(p=>`<div class=\"presentation-row\"><strong>${esc(presentationDisplay(p))}</strong><span>${esc([p.form,p.unitsPerPackage?`${p.unitsPerPackage} un./caixa`:null,p.unitsPerBlister?`${p.unitsPerBlister} un./cartela`:null].filter(Boolean).join(' · '))}</span></div>`).join(''):'<div class=\"registry-empty\">Nenhuma apresentação.</div>'}</div><p class=\"section-mini-title\">Custo e duração</p><div class=\"package-usage-list\">${cost?packageUsageHTML(cost,m):'<div class=\"registry-empty\">Adicione unidades por caixa e registre compras/administrações para calcular.</div>'}</div><p class=\"section-mini-title\">Anotações sobre o medicamento</p><div class=\"med-note-list\">${(m.notes||[]).length?(m.notes||[]).slice().sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).map(n=>`<div class=\"med-note-row\"><strong>${new Date(n.timestamp).toLocaleDateString('pt-BR')}</strong><span>${esc(n.text)}</span></div>`).join(''):'<div class=\"registry-empty\">Nenhuma anotação específica ainda.</div>'}</div><div class=\"field\"><label>Nova anotação</label><textarea id=\"medProfileNote\" placeholder=\"Efeito positivo, incômodo, informação para próxima consulta…\"></textarea></div><button type=\"button\" class=\"primary-button full-button\" id=\"addMedNoteBtn\">Adicionar anotação</button>${suggestions.length?`<p class=\"section-mini-title\">Talvez você queira registrar</p><div class=\"suggested-note-list\">${suggestions.map(s=>`<div class=\"suggested-note\"><p>“${esc(s.note.text)}”</p><small>${esc(`${Math.round(s.diff/60000)} min após ${s.admin.medication}${s.admin.dose?` ${s.admin.dose}`:''}`)}</small><button type=\"button\" data-accept-suggestion=\"${s.note.id}\" data-admin-id=\"${s.admin.id}\">Adicionar às anotações</button></div>`).join('')}</div>`:''}<div class=\"registry-toolbar\"><button type=\"button\" class=\"secondary-button\" data-cancel>Fechar</button><button type=\"button\" class=\"danger-row secondary-button\" id=\"deleteMedBtn\">Excluir cadastro</button></div>`);document.getElementById('editMedBtn').onclick=()=>openMedicationEditor(m);document.getElementById('addPresentationBtn').onclick=()=>openPresentationEditor(m);document.getElementById('addMedNoteBtn').onclick=async()=>{const text=document.getElementById('medProfileNote').value.trim();if(!text)return;m.notes=[...(m.notes||[]),{id:uid('mednote'),timestamp:new Date().toISOString(),text,source:'manual'}];await putMedication(m);toast('Anotação adicionada.');openMedicationDetail(m.id)};document.querySelectorAll('[data-accept-suggestion]').forEach(b=>b.onclick=async()=>{const note=events.find(e=>e.id===b.dataset.acceptSuggestion),admin=events.find(e=>e.id===b.dataset.adminId);if(!note)return;m.notes=[...(m.notes||[]),{id:uid('mednote'),timestamp:note.timestamp,text:note.text,source:'suggested',sourceEventId:note.id,sourceAdministrationId:admin?.id}];await putMedication(m);toast('Relato adicionado sem atribuir causalidade.');openMedicationDetail(m.id)});document.getElementById('deleteMedBtn').onclick=async()=>{if(confirm('Excluir apenas o cadastro? Os registros históricos continuam existindo.')){await deleteMedication(m.id);toast('Cadastro excluído.');openMedicationRegistry()}}}\nfunction packageUsageHTML(cost,m){const rows=cost.lots.slice().sort((a,b)=>b.start-a.start).slice(0,8);return rows.map((lot,i)=>{const pres=findPresentation(m,lot.presentationId),days=((lot.finishedAt||Date.now())-lot.start)/86400000,status=lot.remaining<=0?'Finalizada':`${Math.round(lot.remaining)} de ${lot.units} un. restantes`,unit=lot.price==null?null:lot.price/lot.units,blister=unit!=null&&Number(pres?.unitsPerBlister)?unit*Number(pres.unitsPerBlister):null;return`<div class=\"package-row\"><strong>Caixa ${rows.length-i} · ${esc(pres?presentationDisplay(pres):'apresentação não vinculada')}</strong><span>${status} · duração ${days.toFixed(1).replace('.',',')} ${Math.abs(days-1)<.000001?'dia':'dias'}${unit!=null?` · ${money(unit)}/un.`:''}${blister!=null?` · ${money(blister)}/cartela`:''}</span></div>`}).join('')+`${cost.monthly!=null?`<div class=\"analysis-row\"><strong>Custo dos últimos 30 dias</strong><span>${money(cost.monthly)} com base nas unidades administradas registradas e no último custo por unidade conhecido.</span></div>`:''}`}\nfunction medicationNoteSuggestions(m,events){const admins=events.filter(e=>e.type==='medication'&&medMatchesEvent(m,e)),notes=events.filter(e=>e.type==='note'&&e.text),linked=new Set((m.notes||[]).map(n=>n.sourceEventId).filter(Boolean)),out=[];for(const a of admins){const st=new Date(a.timestamp).getTime();for(const n of notes){const t=new Date(n.timestamp).getTime(),diff=t-st;if(diff>=0&&diff<=6*3600000&&!linked.has(n.id))out.push({admin:a,note:n,diff})}}const seen=new Set();return out.sort((a,b)=>a.diff-b.diff).filter(x=>!seen.has(x.note.id)&&seen.add(x.note.id)).slice(0,6)}\n";document.head.appendChild(s);s.remove();})();

